INSERT INTO `wp_posts` VALUES (64,1,'2026-09-23 15:53:35','2026-09-23 20:53:35','<em>Polera con capucha de corte oversize, confeccionada en algodón perchado de alto gramaje. Cuenta con bolsillo canguro frontal, cordones ajustables y puños acanalados. Ideal para un look urbano y abrigador.</em>','Hoodie Minimal Streetwear','Polera oversize de algodón perchado con capucha y bolsillo canguro.','publish','open','closed','','hoodie-minimal-streetwear','','','2026-09-29 14:21:22','2026-09-29 19:21:22','',0,'http://localhost/wordpress/?post_type=product&#038;p=64',0,'product','',0);
