INSERT INTO `wp_term_taxonomy` VALUES (16,16,'product_cat','Poleras y hoodies urbanos con estilo minimalista, corte oversize y maximo confort.',0,5);
INSERT INTO `wp_term_taxonomy` VALUES (17,17,'product_cat','Polos de corte clásico y oversize confeccionados en algodón suave de alta calidad. Diseños minimalistas, frescos y versátiles pensados para el estilo urbano diario.\r\n\r\n',0,3);
INSERT INTO `wp_term_taxonomy` VALUES (18,18,'product_cat','Pantalones cargo con bolsillos funcionales, jeans rígidos y modelos Wide Leg. Prendas resistentes diseñadas para ofrecer comodidad, durabilidad y tendencia streetwear.',0,4);
INSERT INTO `wp_term_taxonomy` VALUES (19,19,'product_cat','Vestidos casuales modernos que combinan frescura, elegancia juvenil y ligereza. Diseños versátiles y cómodos ideales tanto para el día a día como para salidas de fin de semana.\r\n\r\n',0,1);
INSERT INTO `wp_term_taxonomy` VALUES (20,20,'product_cat','Calzado urbano con suela ergonómica y acabados de primera. El balance perfecto entre confort para caminar todo el día y un diseño vanguardista que eleva cualquier outfit.\r\n\r\n',0,1);
INSERT INTO `wp_term_taxonomy` VALUES (21,21,'product_cat','Gorras de béisbol estructuradas, bolsos tote y complementos esenciales de moda urbana pensados para darle el toque final y distintivo a tu estilo.',0,2);
